import{_ as e,o as a,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"报错解决","description":"","frontmatter":{"title":"报错解决","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/一、构建SpringBoot项目/报错解决.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/一、构建SpringBoot项目/报错解决.md"}'),l={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/A-入门/一、构建SpringBoot项目/报错解决.md"};function r(d,t,s,n,c,p){return a(),o("div",null,[...t[0]||(t[0]=[i('<div><p>如果插件报错： 如<code>Plugin &#39;org.flywaydb:flyway-maven-plugin:&#39; not found</code> 加上版本号即可 报错时：</p><ul><li>&lt;plugin&gt;</li><li>&lt;groupId&gt;org.flywaydb&lt;/groupId&gt;</li><li>&lt;artifactId&gt;flyway-maven-plugin&lt;/artifactId&gt;</li><li>&lt;/plugin&gt;</li></ul><p>加上版本号不再报错：</p><ul><li>&lt;plugin&gt;</li><li>&lt;groupId&gt;org.flywaydb&lt;/groupId&gt;</li><li>&lt;artifactId&gt;flyway-maven-plugin&lt;/artifactId&gt;</li><li>&lt;version&gt;9.4.0&lt;/version&gt;</li><li>&lt;/plugin&gt;</li></ul><p><code>spring Cannot resolve symbol</code> ‘<code>validation</code>‘</p><p>&gt; 安装依赖：</p><p>&lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-validation&lt;/artifactId&gt; &lt;/dependency&gt; 报错：<code>Failed to configure a DataSource: &#39;url&#39; attribute is not specified and no embedd</code> 翻译就是：无法配置<code>DataSource</code>：未指定<code>&#39;url&#39;</code>属性，也无法配置嵌入数据源。 原因是没有配置数据库，如：地址值啊，数据库驱动啊，用户名啊，密码等； 可以在<code>application.properties</code>或<code>appliction.yml</code>文件中配置： 最基本的配置： <code>#</code>应用名称</p><ul><li>spring.application.name=springboot-demo</li><li><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>访问端口号</p><ul><li>server.port=8080</li><li><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>编码格式</p><ul><li>server.tomcat.uri-encoding=utf-8</li><li><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>数据库相关配置</p><p>spring.datasource.driver-class-name=com.mysql.cj.jdbc.Driver spring.datasource.url=jdbc:mysql://localhost:3306/sql_test spring.datasource.username=root spring.datasource.password=123456 spring.datasource.max-idle=10 spring.datasource.max-wait=10000 spring.datasource.min-idle=5 spring.datasource.initial-size=5 #session 生命周期 <code>server.servlet.session.timeout=30m</code></p><p><code>Application.yml</code>中配置：</p><p>spring: datasource: url: jdbc:mysql://localhost:3306/test?useUnicode=true&amp;characterEncoding=UTF-8&amp;useSSL=false username: root password: 123456 driver-class-name: com.mysql.jdbc.Driver 如果暂时不用数据库，可以在启动类头部声明：</p><p><code>#mysql8</code>以下的<code>url</code>写法 <code>url: jdbc:mysql://localhost:3306/test?useUnicode=true&amp;characterEncoding=UTF-8&amp;useSSL=false</code></p></div>',1)])])}const m=e(l,[["render",r]]);export{u as __pageData,m as default};
